//! The names of the client's scripts, for the Script Inspector.
//!
//! The cache has none, so `script_names.tsv` (generated by `tools/scriptnames/gen.py` from RuneLite's decompiled scripts)
//! holds the community's names, keyed by the cache's script id: they are right for the build the table was made from.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("script_names.tsv");

struct Names {
    by_id: HashMap<i32, &'static str>,
    by_name: HashMap<String, Vec<i32>>,
}

fn names() -> &'static Names {
    static NAMES: OnceLock<Names> = OnceLock::new();
    NAMES.get_or_init(|| {
        let mut names = Names { by_id: HashMap::new(), by_name: HashMap::new() };
        for line in TABLE.lines().filter(|line| !line.starts_with('#')) {
            if let Some((id, name)) = line.split_once('\t')
                && let Ok(id) = id.parse()
            {
                names.by_id.insert(id, name);
                names.by_name.entry(name.to_ascii_lowercase()).or_default().push(id);
            }
        }
        names
    })
}

/// The name of script `id`, if the table has one.
pub fn name(id: i32) -> Option<&'static str> {
    names().by_id.get(&id).copied()
}

/// The ids named `name`, in any case; a client script and a proc can share a name.
pub fn ids(name: &str) -> &'static [i32] {
    names().by_name.get(&name.to_ascii_lowercase()).map_or(&[], Vec::as_slice)
}

/// The build the table was made from, as `date commit`.
#[cfg(test)]
pub fn source() -> &'static str {
    TABLE.lines().find_map(|line| line.strip_prefix("# source\t")).unwrap_or("unknown")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_and_names_find_each_other() {
        assert_eq!(name(6697), Some("npc_name_timer"));
        assert_eq!(ids("NPC_name_timer"), [6697]);
        assert_eq!(name(-5), None);
        assert!(ids("no_such_script").is_empty());
        assert_ne!(source(), "unknown");
    }
}
